import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

// IDs are UUIDv7 (time-ordered), generated by the API so keyset pagination
// on id follows creation order.

const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();

export const ROLES = [
  'learner',
  'admin',
  'content_editor',
  'legal_reviewer',
  'publisher',
  'analyst',
] as const;
export type Role = (typeof ROLES)[number];

export const users = pgTable('users', {
  id: uuid('id').primaryKey(),
  email: text('email').notNull().unique(), // stored lower-cased
  displayName: text('display_name').notNull(),
  passwordHash: text('password_hash').notNull(),
  roles: text('roles').array().$type<Role[]>().notNull(),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** Opaque refresh tokens; only a SHA-256 hash is stored. Rotated on use. */
export const refreshTokens = pgTable(
  'refresh_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('refresh_tokens_user_idx').on(t.userId)],
);

/** Every role except learner: the accounts admins manage on the Staff page. */
export const STAFF_ROLES = ROLES.filter(
  (r): r is Exclude<Role, 'learner'> => r !== 'learner',
);

/**
 * One-time links for a staff member to choose their password: made when an
 * admin invites them or resets their access. Only a SHA-256 hash is stored;
 * a link works once, until it expires, and a newer link replaces it.
 */
export const staffSetupTokens = pgTable(
  'staff_setup_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
  },
  (t) => [index('staff_setup_tokens_user_idx').on(t.userId)],
);

// ---------------------------------------------------------------- taxonomy

export const subjects = pgTable('subjects', {
  id: uuid('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
  sortOrder: integer('sort_order').notNull().default(0),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const acts = pgTable('acts', {
  id: uuid('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  shortName: text('short_name'),
  year: smallint('year'),
  jurisdiction: text('jurisdiction').notNull().default('IN'),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const topics = pgTable(
  'topics',
  {
    id: uuid('id').primaryKey(),
    subjectId: uuid('subject_id')
      .notNull()
      .references(() => subjects.id),
    actId: uuid('act_id').references(() => acts.id),
    slug: text('slug').notNull().unique(),
    name: text('name').notNull(),
    description: text('description'),
    sortOrder: integer('sort_order').notNull().default(0),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('topics_subject_idx').on(t.subjectId)],
);

// ---------------------------------------------------------------- questions

export const VERSION_STATUSES = [
  'draft',
  'in_review',
  'changes_requested',
  'approved',
  'published',
  'superseded',
  'retired',
] as const;
export type VersionStatus = (typeof VERSION_STATUSES)[number];
export const versionStatus = pgEnum(
  'question_version_status',
  VERSION_STATUSES,
);

export const QUESTION_TYPES = ['single_select'] as const;
export type QuestionType = (typeof QUESTION_TYPES)[number];
export const questionType = pgEnum('question_type', QUESTION_TYPES);

export interface QuestionOption {
  id: string;
  text: string;
}

/** Stable identity of a question across all its versions. */
export const questions = pgTable('questions', {
  id: uuid('id').primaryKey(),
  /** Id in an outside source (e.g. the app's bundled bank), for idempotent imports. */
  externalRef: text('external_ref').unique(),
  liveVersionId: uuid('live_version_id').references(
    (): AnyPgColumn => questionVersions.id,
  ),
  createdBy: uuid('created_by').references(() => users.id),
  retiredAt: timestamp('retired_at', { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * One revision of a question. Only the latest version of a question can
 * change, and only while it is a draft or has changes requested; a published
 * version is immutable and a correction is a new version.
 */
export const questionVersions = pgTable(
  'question_versions',
  {
    id: uuid('id').primaryKey(),
    questionId: uuid('question_id')
      .notNull()
      .references(() => questions.id),
    versionNo: integer('version_no').notNull(),
    status: versionStatus('status').notNull().default('draft'),
    topicId: uuid('topic_id')
      .notNull()
      .references(() => topics.id),
    jurisdiction: text('jurisdiction').notNull().default('IN'),
    language: text('language').notNull().default('en'),
    questionType: questionType('question_type')
      .notNull()
      .default('single_select'),
    difficulty: smallint('difficulty').notNull().default(1),
    stem: text('stem').notNull().default(''),
    options: jsonb('options').$type<QuestionOption[]>().notNull().default([]),
    correctOptionIds: text('correct_option_ids')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    explanation: text('explanation').notNull().default(''),
    sourceTitle: text('source_title'),
    sourceUrl: text('source_url'),
    citation: text('citation'),
    provisionReference: text('provision_reference'),
    validFrom: date('valid_from'),
    validTo: date('valid_to'),
    verifiedAt: timestamp('verified_at', { withTimezone: true }),
    reviewerId: uuid('reviewer_id').references(() => users.id),
    changeNote: text('change_note'),
    createdBy: uuid('created_by').references(() => users.id),
    updatedBy: uuid('updated_by').references(() => users.id),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    approvedAt: timestamp('approved_at', { withTimezone: true }),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    publishedBy: uuid('published_by').references(() => users.id),
    endedAt: timestamp('ended_at', { withTimezone: true }), // superseded or retired
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('question_versions_question_no_idx').on(
      t.questionId,
      t.versionNo,
    ),
    index('question_versions_status_idx').on(t.status),
    index('question_versions_topic_idx').on(t.topicId),
    check('difficulty_range', sql`${t.difficulty} between 1 and 3`),
  ],
);

export const REVIEW_DECISIONS = ['approved', 'changes_requested'] as const;
export const reviewDecision = pgEnum('review_decision', REVIEW_DECISIONS);

export const reviewDecisions = pgTable(
  'review_decisions',
  {
    id: uuid('id').primaryKey(),
    versionId: uuid('version_id')
      .notNull()
      .references(() => questionVersions.id),
    reviewerId: uuid('reviewer_id')
      .notNull()
      .references(() => users.id),
    decision: reviewDecision('decision').notNull(),
    reason: text('reason'),
    createdAt: createdAt(),
  },
  (t) => [index('review_decisions_version_idx').on(t.versionId)],
);

/** Append-only record of sensitive actions. Never updated or deleted. */
export const auditLog = pgTable(
  'audit_log',
  {
    id: uuid('id').primaryKey(),
    actorId: uuid('actor_id').references(() => users.id),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id'),
    data: jsonb('data').$type<Record<string, unknown>>(),
    requestId: text('request_id'),
    createdAt: createdAt(),
  },
  (t) => [index('audit_log_entity_idx').on(t.entityType, t.entityId)],
);

// ---------------------------------------------------------------- learning

/**
 * immediate: each answer is final and its explanation is returned at once
 * (practice). end: answers can change until submit and nothing is revealed
 * before it (exam). Follows from the session's mode, so it is not stored.
 */
export const FEEDBACK_MODES = ['immediate', 'end'] as const;
export type FeedbackMode = (typeof FEEDBACK_MODES)[number];

/** The app's four ways to play; decides feedback, rewards and the daily set. */
export const QUIZ_MODES = [
  'case_path',
  'daily_docket',
  'duel',
  'exam',
  'mistake_review',
] as const;
export type QuizMode = (typeof QUIZ_MODES)[number];
export const quizMode = pgEnum('quiz_mode', QUIZ_MODES);

/**
 * One attempt at a quiz. The server picks the questions and owns the result.
 * In progress until submitted_at is set. Feedback, the daily set's date, the
 * deadline and the score are worked out from these columns, not stored.
 */
export const quizSessions = pgTable(
  'quiz_sessions',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    mode: quizMode('mode').notNull(),
    language: text('language').notNull(),
    /** One difficulty is stored as min = max; null means any. */
    minDifficulty: smallint('min_difficulty'),
    maxDifficulty: smallint('max_difficulty'),
    scoringVersion: text('scoring_version').notNull(),
    questionCount: integer('question_count').notNull(),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    correctCount: integer('correct_count'),
    answeredCount: integer('answered_count'),
    /** XP given at submit; depends on the streak and best stars at that time. */
    xpAwarded: integer('xp_awarded'),
  },
  (t) => [index('quiz_sessions_user_idx').on(t.userId, t.id)],
);

/** Topics a session's questions were drawn from; none means every topic. */
export const quizSessionTopics = pgTable(
  'quiz_session_topics',
  {
    sessionId: uuid('session_id')
      .notNull()
      .references(() => quizSessions.id, { onDelete: 'cascade' }),
    topicId: uuid('topic_id')
      .notNull()
      .references(() => topics.id),
  },
  (t) => [primaryKey({ columns: [t.sessionId, t.topicId] })],
);

/**
 * The exact question versions a session showed, in order. Versions are
 * immutable, so results stay reproducible after a question is revised.
 */
export const quizSessionQuestions = pgTable(
  'quiz_session_questions',
  {
    sessionId: uuid('session_id')
      .notNull()
      .references(() => quizSessions.id, { onDelete: 'cascade' }),
    position: smallint('position').notNull(),
    questionVersionId: uuid('question_version_id')
      .notNull()
      .references(() => questionVersions.id),
    /** Option ids in the order this learner sees them. */
    optionOrder: text('option_order').array().notNull(),
    selectedOptionIds: text('selected_option_ids').array(),
    answeredAt: timestamp('answered_at', { withTimezone: true }),
    isCorrect: boolean('is_correct'),
  },
  (t) => [
    primaryKey({ columns: [t.sessionId, t.position] }),
    uniqueIndex('quiz_session_questions_version_idx').on(
      t.sessionId,
      t.questionVersionId,
    ),
  ],
);

/** AI chat answers per learner per India date, for the daily limit. */
export const chatUsage = pgTable(
  'chat_usage',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    day: date('day').notNull(),
    answers: integer('answers').notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.userId, t.day] })],
);

/** Chapter chests a learner has opened on the Case Path road (one per subject). */
export const chestOpenings = pgTable(
  'chest_openings',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    subjectId: uuid('subject_id')
      .notNull()
      .references(() => subjects.id),
    openedAt: timestamp('opened_at', { withTimezone: true }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.subjectId] })],
);

// ---------------------------------------------------------------- economy

/**
 * Why coins moved. Earning: welcome (once), new_stars, daily_docket,
 * daily_goal and streak_milestone (per quiz session), chest (per subject).
 * Spending: energy_refill, streak_freeze (the freeze purchase itself).
 * league_top3: finishing a week in the top 3 of a league group (per cohort).
 */
export const COIN_REASONS = [
  'welcome',
  'new_stars',
  'daily_docket',
  'daily_goal',
  'streak_milestone',
  'chest',
  'energy_refill',
  'streak_freeze',
  'league_top3',
] as const;
export type CoinReason = (typeof COIN_REASONS)[number];
export const coinReason = pgEnum('coin_reason', COIN_REASONS);

/**
 * Every coin earned (+) or spent (−). The balance is the sum, never stored.
 * A reward is paid once per session or chest (partial unique indexes).
 */
export const coinLedger = pgTable(
  'coin_ledger',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    amount: integer('amount').notNull(),
    reason: coinReason('reason').notNull(),
    sessionId: uuid('session_id').references(() => quizSessions.id, {
      onDelete: 'set null',
    }),
    subjectId: uuid('subject_id').references(() => subjects.id),
    /** league_top3: the league group the bonus is for. */
    cohortId: uuid('cohort_id').references((): AnyPgColumn => leagueCohorts.id),
    createdAt: createdAt(),
  },
  (t) => [
    index('coin_ledger_user_idx').on(t.userId),
    uniqueIndex('coin_ledger_cohort_idx')
      .on(t.userId, t.cohortId)
      .where(sql`${t.cohortId} is not null`),
    uniqueIndex('coin_ledger_session_reason_idx')
      .on(t.userId, t.reason, t.sessionId)
      .where(sql`${t.sessionId} is not null`),
    uniqueIndex('coin_ledger_chest_idx')
      .on(t.userId, t.subjectId)
      .where(sql`${t.reason} = 'chest'`),
    uniqueIndex('coin_ledger_welcome_idx')
      .on(t.userId)
      .where(sql`${t.reason} = 'welcome'`),
  ],
);

/** quiz_start (−cost), quiz_refund (quit before answering), three_star_bonus, refill. */
export const ENERGY_REASONS = [
  'quiz_start',
  'quiz_refund',
  'three_star_bonus',
  'refill',
] as const;
export type EnergyReason = (typeof ENERGY_REASONS)[number];
export const energyReason = pgEnum('energy_reason', ENERGY_REASONS);

/**
 * Energy used and gained. Today's energy is the free daily amount plus the
 * rows dated today (India), so nothing has to be reset at midnight.
 */
export const energyLedger = pgTable(
  'energy_ledger',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    amount: integer('amount').notNull(),
    reason: energyReason('reason').notNull(),
    sessionId: uuid('session_id').references(() => quizSessions.id, {
      onDelete: 'set null',
    }),
    createdAt: createdAt(),
  },
  (t) => [
    index('energy_ledger_user_idx').on(t.userId, t.createdAt),
    uniqueIndex('energy_ledger_session_reason_idx')
      .on(t.sessionId, t.reason)
      .where(sql`${t.sessionId} is not null`),
  ],
);

export const PERSONAS = ['advocate', 'aspirant', 'citizen'] as const;
export const persona = pgEnum('persona', PERSONAS);

/**
 * Learning settings that follow the account (the name is users.display_name).
 * Theme, sound, haptics and reminders stay on each phone.
 */
export const learnerSettings = pgTable('learner_settings', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  persona: persona('persona').notNull(),
  language: text('language').notNull(),
  dailyGoal: smallint('daily_goal').notNull(),
  onboardedAt: timestamp('onboarded_at', { withTimezone: true }),
  updatedAt: updatedAt(),
});

/**
 * Premium learners. A row means premium. Until real store purchases exist the
 * app turns it on itself (source 'demo', testing only).
 */
export const premiumMemberships = pgTable('premium_memberships', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  source: text('source').notNull(),
  startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
});

// ---------------------------------------------------------------- leagues

/**
 * One weekly league group of up to 30 learners at one tier. Weeks are ISO
 * weeks in India time (`2026-W44`). Standings, results and tier changes are
 * worked out from the members' quiz XP, not stored.
 */
export const leagueCohorts = pgTable(
  'league_cohorts',
  {
    id: uuid('id').primaryKey(),
    weekId: text('week_id').notNull(),
    tier: smallint('tier').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('league_cohorts_week_tier_idx').on(t.weekId, t.tier),
    // Lets memberships check that their week matches their group's week.
    uniqueIndex('league_cohorts_id_week_idx').on(t.id, t.weekId),
  ],
);

/** A learner's group for one week; one group per learner per week. */
export const leagueMemberships = pgTable(
  'league_memberships',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    weekId: text('week_id').notNull(),
    cohortId: uuid('cohort_id').notNull(),
    joinedAt: timestamp('joined_at', { withTimezone: true }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.weekId] }),
    index('league_memberships_cohort_idx').on(t.cohortId),
    foreignKey({
      columns: [t.cohortId, t.weekId],
      foreignColumns: [leagueCohorts.id, leagueCohorts.weekId],
    }).onDelete('cascade'),
  ],
);

// ---------------------------------------------------------------- review & reports

/**
 * Questions a learner saved. Points at the question, not a version, so a
 * saved question shows its latest version and survives revisions.
 */
export const questionBookmarks = pgTable(
  'question_bookmarks',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    questionId: uuid('question_id')
      .notNull()
      .references(() => questions.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.questionId] })],
);

export const REPORT_REASONS = [
  'wrong_answer',
  'unclear',
  'outdated_law',
  'typo',
  'other',
] as const;
export type ReportReason = (typeof REPORT_REASONS)[number];
export const reportReason = pgEnum('report_reason', REPORT_REASONS);

/** How staff closed a report: the question was fixed, retired, or needed no change. */
export const REPORT_OUTCOMES = ['fixed', 'retired', 'no_change'] as const;
export type ReportOutcome = (typeof REPORT_OUTCOMES)[number];
export const reportOutcome = pgEnum('report_outcome', REPORT_OUTCOMES);

/**
 * A learner's report about the exact question version they saw. Reports
 * never change content; staff fix or retire the question, then close the
 * report. Open = no outcome yet (not stored separately); the question
 * follows from the version.
 */
export const contentReports = pgTable(
  'content_reports',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    questionVersionId: uuid('question_version_id')
      .notNull()
      .references(() => questionVersions.id),
    reason: reportReason('reason').notNull(),
    comment: text('comment'),
    createdAt: createdAt(),
    outcome: reportOutcome('outcome'),
    resolvedBy: uuid('resolved_by').references(() => users.id),
    resolvedAt: timestamp('resolved_at', { withTimezone: true }),
    resolutionNote: text('resolution_note'),
  },
  (t) => [
    index('content_reports_open_idx').on(t.outcome, t.createdAt),
    index('content_reports_version_idx').on(t.questionVersionId),
    // One open report per learner per question version.
    uniqueIndex('content_reports_open_per_user_idx')
      .on(t.userId, t.questionVersionId)
      .where(sql`${t.outcome} is null`),
    // Closed reports say how, by whom and when; open ones say none of it.
    check(
      'content_reports_resolution_check',
      sql`(${t.outcome} is null) = (${t.resolvedAt} is null) and (${t.outcome} is null) = (${t.resolvedBy} is null)`,
    ),
  ],
);

// ---------------------------------------------------------------- imports

export const IMPORT_FORMATS = ['csv', 'xlsx'] as const;
export const importFormat = pgEnum('import_format', IMPORT_FORMATS);

/** What happened to one row: a new draft, an existing question, or nothing. */
export const IMPORT_OUTCOMES = ['created', 'skipped', 'failed'] as const;
export type ImportOutcome = (typeof IMPORT_OUTCOMES)[number];
export const importOutcome = pgEnum('import_outcome', IMPORT_OUTCOMES);

export const PROBLEM_LEVELS = ['error', 'warning'] as const;
export type ProblemLevel = (typeof PROBLEM_LEVELS)[number];
export const problemLevel = pgEnum('problem_level', PROBLEM_LEVELS);

/**
 * A file of questions imported as drafts. Test runs are not stored. The same
 * file (by content) can be imported only once. Counts follow from the rows.
 */
export const importJobs = pgTable('import_jobs', {
  id: uuid('id').primaryKey(),
  createdBy: uuid('created_by')
    .notNull()
    .references(() => users.id),
  fileName: text('file_name').notNull(),
  fileSha256: text('file_sha256').notNull().unique(),
  format: importFormat('format').notNull(),
  createdAt: createdAt(),
});

/** One data row of an imported file, by its line in the file (header = 1). */
export const importJobRows = pgTable(
  'import_job_rows',
  {
    jobId: uuid('job_id')
      .notNull()
      .references(() => importJobs.id, { onDelete: 'cascade' }),
    line: integer('line').notNull(),
    externalRef: text('external_ref'),
    outcome: importOutcome('outcome').notNull(),
    /** The draft it created, or the existing question it duplicates. */
    questionId: uuid('question_id').references(() => questions.id),
  },
  (t) => [
    primaryKey({ columns: [t.jobId, t.line] }),
    index('import_job_rows_question_idx').on(t.questionId),
    check(
      'import_job_rows_question_check',
      sql`(${t.outcome} <> 'created' or ${t.questionId} is not null) and (${t.outcome} <> 'failed' or ${t.questionId} is null)`,
    ),
  ],
);

/** Errors (row not imported) and warnings (imported, but not ready for review). */
export const importRowProblems = pgTable(
  'import_row_problems',
  {
    jobId: uuid('job_id').notNull(),
    line: integer('line').notNull(),
    position: smallint('position').notNull(),
    level: problemLevel('level').notNull(),
    field: text('field'),
    reason: text('reason').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.jobId, t.line, t.position] }),
    foreignKey({
      columns: [t.jobId, t.line],
      foreignColumns: [importJobRows.jobId, importJobRows.line],
    }).onDelete('cascade'),
  ],
);

// ---------------------------------------------------------------- analytics

/**
 * One row per learner per India date they opened the app: the only usage the
 * server does not already know from quizzes and chat, needed for retention.
 * No device ids or screens. Removed with the account.
 */
export const appOpens = pgTable(
  'app_opens',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    day: date('day').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.day] }),
    index('app_opens_day_idx').on(t.day),
  ],
);
